'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { CheckIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Spinner } from '@/registry/ndeko/ui/spinner';

import { EditorTiles, OptionSwitch, type Option } from './choices';
import { ConfigBlock } from './config-block';
import {
  editorOf,
  SERVER,
  snippetOf,
  type Editor,
  type Scope,
  type Snippet,
  type Transport,
} from './data';
import {
  CONNECT_MS,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type Connection,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const TRANSPORTS: Option<Transport>[] = [
  { value: 'remote', label: 'Remote' },
  { value: 'local', label: 'Local' },
];

const SCOPES: Option<Scope>[] = [
  { value: 'project', label: 'This project' },
  { value: 'everywhere', label: 'Everywhere' },
];

type EdgeStyle = React.CSSProperties & { '--edge': string };

/** The edge takes the colour of the editor the card waits for, and keeps it once connected. */
function edgeOf(isLit: boolean) {
  if (isLit) {
    return 'ring-2 ring-(--edge)';
  }
  return 'hairline-ring ring-border';
}

/** An editor with one list of servers has no project choice to offer. */
function shownScopeOf(editor: Editor, scope: Scope): Scope {
  if (editor.scopeNote) {
    return 'everywhere';
  }
  return scope;
}

function idleLineOf(snippet: Snippet, editor: Editor) {
  if (snippet.language === 'bash') {
    return 'Copy the command and run it in a terminal';
  }
  if (snippet.language === 'fields') {
    return `Copy the values into the MCP settings of ${editor.name}`;
  }
  return `Copy the config into ${snippet.label}`;
}

function toolsWordOf(count: number) {
  if (count === 1) {
    return '1 tool';
  }
  return `${count} tools`;
}

function statusLineOf(
  connection: Connection,
  snippet: Snippet,
  editor: Editor
) {
  if (connection === 'waiting') {
    return `Waiting for the first connection from ${editor.name}`;
  }
  if (connection === 'connected') {
    return `Connected, ${toolsWordOf(SERVER.toolCount)}`;
  }
  return idleLineOf(snippet, editor);
}

function statusToneOf(connection: Connection) {
  if (connection === 'idle') {
    return 'text-muted-foreground';
  }
  return 'text-foreground';
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

export default function AgentOps05() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const editor = editorOf(state.editorId);
  const scope = shownScopeOf(editor, state.scope);
  const snippet = snippetOf(editor.id, state.transport, scope);
  const configKey = `${editor.id}:${state.transport}:${scope}`;
  const isCopied = state.connection !== 'idle';
  const isWaiting = state.connection === 'waiting';
  const isConnected = state.connection === 'connected';
  const hasScopeNote = editor.scopeNote !== undefined;
  const statusLine = statusLineOf(state.connection, snippet, editor);
  const edgeStyle: EdgeStyle = { '--edge': seriesColorOf(editor.series) };
  const message = spokenUnless(isAutoplaying, statusLine);
  const canReplay = isFinished && !isAutoplaying;

  async function copy() {
    try {
      await navigator.clipboard.writeText(snippet.copyText);
    } catch {
      return;
    }
    act({ type: 'copied' });
    schedule(() => act({ type: 'connected' }), CONNECT_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-2xl flex-col gap-5 p-4 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <BrandTile brand='mcp' size='lg' />
            <div className='flex min-w-40 flex-1 flex-col gap-0.5 leading-tight'>
              <h1 className='text-lg font-semibold text-balance'>
                Add {SERVER.title} to your editor
              </h1>
              <code className='text-muted-foreground truncate font-mono text-xs'>
                {SERVER.url}
              </code>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the install'
            />
          </header>

          <section
            aria-label='Install'
            style={edgeStyle}
            className={cn(
              'bg-card dark:bg-foreground/[0.03] flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-shadow duration-300 ease-(--ease-out-strong)',
              edgeOf(isCopied)
            )}
          >
            <EditorTiles
              value={editor.id}
              onValueChange={(id) => act({ type: 'editor', id })}
            />

            <div className='flex flex-col gap-2'>
              <div className='flex flex-wrap items-center gap-2'>
                <OptionSwitch
                  label='Where the server runs'
                  value={state.transport}
                  options={TRANSPORTS}
                  onValueChange={(transport) =>
                    act({ type: 'transport', transport })
                  }
                  className='w-40'
                />
                <OptionSwitch
                  label='Where the editor uses it'
                  value={scope}
                  options={SCOPES}
                  isDisabled={hasScopeNote}
                  onValueChange={(next) => act({ type: 'scope', scope: next })}
                  className='w-52'
                />
              </div>
              <Fold open={hasScopeNote}>
                <p className='text-muted-foreground text-xs'>
                  {editor.scopeNote}
                </p>
              </Fold>
            </div>

            <ConfigBlock
              editorId={editor.id}
              configKey={configKey}
              snippet={snippet}
              isCopied={isCopied}
              isCopyPressed={pressed === 'copy'}
              onCopy={copy}
            />

            <p
              className={cn(
                'flex min-h-6 items-center gap-2 text-[13px] transition-colors duration-200',
                statusToneOf(state.connection)
              )}
            >
              <Swap swapKey={state.connection} className='size-4 shrink-0'>
                {isWaiting && <Spinner label='Waiting' />}
                {isConnected && (
                  <CheckIcon className='text-success-foreground size-4' />
                )}
                {!isCopied && (
                  <span
                    aria-hidden='true'
                    className='bg-muted-foreground/40 m-auto size-1.5 rounded-full'
                  />
                )}
              </Swap>
              <Swap swapKey={statusLine}>{statusLine}</Swap>
            </p>
          </section>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { LetterTile } from '@/registry/ndeko/ui/letter-tile';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { EDITORS, type Editor, type EditorId } from './data';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

function EditorMark({ editor }: { editor: Editor }) {
  if (editor.brand) {
    return <BrandTile brand={editor.brand} size='lg' />;
  }
  return <LetterTile initial={editor.initial} size='lg' />;
}

type EditorTilesProps = {
  value: EditorId;
  onValueChange: (id: EditorId) => void;
};

export function EditorTiles({ value, onValueChange }: EditorTilesProps) {
  function change(values: unknown[]) {
    const [next] = values;
    const editor = EDITORS.find((candidate) => candidate.id === next);
    if (editor) {
      onValueChange(editor.id);
    }
  }

  return (
    <ToggleGroup
      aria-label='Editor'
      value={[value]}
      onValueChange={change}
      travel
      indicatorClassName={THUMB}
      className='bg-foreground/[0.04] grid w-full grid-cols-3 gap-1 rounded-xl p-1 @xl:grid-cols-6'
    >
      {EDITORS.map((editor) => (
        <ToggleGroupItem
          key={editor.id}
          value={editor.id}
          className='h-auto min-w-0 flex-col gap-1.5 rounded-lg px-1 py-2.5 text-xs'
        >
          <EditorMark editor={editor} />
          <span className='max-w-full truncate'>{editor.name}</span>
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

export type Option<Value extends string> = {
  value: Value;
  label: string;
};

type OptionSwitchProps<Value extends string> = {
  label: string;
  value: Value;
  options: readonly Option<Value>[];
  isDisabled?: boolean;
  onValueChange: (value: Value) => void;
  className?: string;
};

/** A segmented switch that can be locked when the editor leaves no choice. */
export function OptionSwitch<Value extends string>({
  label,
  value,
  options,
  isDisabled = false,
  onValueChange,
  className,
}: OptionSwitchProps<Value>) {
  function change(values: unknown[]) {
    const [next] = values;
    const option = options.find((candidate) => candidate.value === next);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <ToggleGroup
      aria-label={label}
      value={[value]}
      onValueChange={change}
      disabled={isDisabled}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className={cn('bg-foreground/[0.05] rounded-lg p-0.5', className)}
    >
      {options.map((option) => (
        <ToggleGroupItem
          key={option.value}
          value={option.value}
          className='h-6 flex-1 rounded-md px-2.5 text-xs'
        >
          {option.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import {
  CheckIcon,
  CopyIcon,
  FileTextIcon,
  SlidersIcon,
  TerminalIcon,
} from '@/registry/ndeko/lib/icons';
import { FADE } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { jsonTokensOf } from '@/registry/ndeko/ui/json-view';

import type { EditorId, Snippet, SnippetLanguage } from './data';

const NO_LINES: string[] = [];

const FADE_IN = { opacity: 1 };

const FADE_OUT = { opacity: 0 };

const TOKEN_CLASS: Record<string, string> = {
  key: 'text-foreground',
  string: 'text-primary-ink',
  number: 'text-muted-foreground',
  literal: 'text-muted-foreground',
  mark: 'text-muted-foreground/60',
  space: '',
};

type Shown = {
  key: string;
  editorId: EditorId;
  lines: string[];
  /** The lines the last change of an option brought in. */
  fresh: string[];
};

/** A line is fresh when an option changed it; a new editor brings a whole new config and none is. */
function freshLinesOf(
  isSameEditor: boolean,
  before: string[],
  after: string[]
) {
  if (!isSameEditor) {
    return NO_LINES;
  }
  return after.filter((line) => !before.includes(line));
}

/** A changed line lights once, then settles back into the block. */
function freshClassOf(isFresh: boolean) {
  if (isFresh) {
    return 'transition-colors duration-1000 ease-out starting:bg-primary/25';
  }
  return undefined;
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07] text-foreground';
  }
  return undefined;
}

function copyWordOf(isCopied: boolean, copyLabel: string) {
  if (isCopied) {
    return 'Copied';
  }
  return copyLabel;
}

function LabelGlyph({ language }: { language: SnippetLanguage }) {
  if (language === 'bash') {
    return <TerminalIcon className='size-3.5 shrink-0' />;
  }
  if (language === 'fields') {
    return <SlidersIcon className='size-3.5 shrink-0' />;
  }
  return <FileTextIcon className='size-3.5 shrink-0' />;
}

type CodeLineProps = {
  line: string;
  language: SnippetLanguage;
};

function CodeLine({ line, language }: CodeLineProps) {
  if (language !== 'json') {
    return <>{line}</>;
  }
  const tokens = jsonTokensOf(line);

  return (
    <>
      {tokens.map((token, index) => (
        <span key={index} className={TOKEN_CLASS[token.kind]}>
          {token.text}
        </span>
      ))}
    </>
  );
}

export type ConfigBlockProps = {
  editorId: EditorId;
  /** Changes with the editor and with each option, so the block knows a new config arrived. */
  configKey: string;
  snippet: Snippet;
  isCopied: boolean;
  isCopyPressed: boolean;
  onCopy: () => void;
};

export function ConfigBlock({
  editorId,
  configKey,
  snippet,
  isCopied,
  isCopyPressed,
  onCopy,
}: ConfigBlockProps) {
  const [shown, setShown] = useState<Shown>(() => ({
    key: configKey,
    editorId,
    lines: snippet.lines,
    fresh: NO_LINES,
  }));
  if (shown.key !== configKey) {
    const isSameEditor = shown.editorId === editorId;
    const fresh = freshLinesOf(isSameEditor, shown.lines, snippet.lines);
    setShown({ key: configKey, editorId, lines: snippet.lines, fresh });
  }
  const copyWord = copyWordOf(isCopied, snippet.copyLabel);

  return (
    <div className='bg-foreground/[0.03] dark:bg-foreground/[0.05] flex flex-col rounded-lg'>
      <div className='flex h-10 items-center gap-2 ps-3 pe-1.5'>
        <span className='text-muted-foreground flex min-w-0 flex-1 items-center gap-2 text-xs'>
          <Swap swapKey={snippet.language}>
            <LabelGlyph language={snippet.language} />
          </Swap>
          <span className='min-w-0 truncate font-mono'>
            <Swap swapKey={snippet.label}>{snippet.label}</Swap>
          </span>
        </span>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          onClick={onCopy}
          className={cn('text-muted-foreground', pressedQuietOf(isCopyPressed))}
        >
          <Swap swapKey={String(isCopied)}>
            {isCopied && <CheckIcon className='text-success-foreground' />}
            {!isCopied && <CopyIcon />}
          </Swap>
          <Swap swapKey={copyWord}>{copyWord}</Swap>
        </Button>
      </div>
      <AnimatedSize className='m-0' contentClassName='relative p-0'>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.pre
            key={editorId}
            initial={FADE_OUT}
            animate={FADE_IN}
            exit={FADE_OUT}
            transition={FADE}
            className='overflow-x-auto px-3 pb-3 font-mono text-xs leading-6'
          >
            <code className='flex min-w-max flex-col'>
              {snippet.lines.map((line, index) => (
                <span
                  key={`${index}:${line}`}
                  className={cn(
                    '-mx-1.5 rounded-sm px-1.5 whitespace-pre',
                    freshClassOf(shown.fresh.includes(line))
                  )}
                >
                  <CodeLine line={line} language={snippet.language} />
                </span>
              ))}
            </code>
          </motion.pre>
        </AnimatePresence>
      </AnimatedSize>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import type { EditorId, Scope, Transport } from './data';

export type Connection = 'idle' | 'waiting' | 'connected';

export type InstallState = {
  editorId: EditorId;
  transport: Transport;
  scope: Scope;
  connection: Connection;
};

export type InstallAction =
  | { type: 'editor'; id: EditorId }
  | { type: 'transport'; transport: Transport }
  | { type: 'scope'; scope: Scope }
  | { type: 'copied' }
  | { type: 'connected' };

type Step = SessionStep<InstallState, InstallAction>;

export const INITIAL: InstallState = {
  editorId: 'claude-code',
  transport: 'remote',
  scope: 'project',
  connection: 'idle',
};

/** A new config has not been copied yet, so the card stops waiting for the old one. */
function changed(
  state: InstallState,
  patch: Partial<InstallState>
): InstallState {
  return { ...state, ...patch, connection: 'idle' };
}

function connected(state: InstallState): InstallState {
  if (state.connection !== 'waiting') {
    return state;
  }
  return { ...state, connection: 'connected' };
}

export function reducer(
  state: InstallState,
  action: InstallAction
): InstallState {
  switch (action.type) {
    case 'editor':
      return changed(state, { editorId: action.id });
    case 'transport':
      return changed(state, { transport: action.transport });
    case 'scope':
      return changed(state, { scope: action.scope });
    case 'copied':
      return { ...state, connection: 'waiting' };
    case 'connected':
      return connected(state);
  }
}

function hasCopied(state: InstallState) {
  return state.connection !== 'idle';
}

/** How long the editor takes to start the server and list its tools. */
export const CONNECT_MS = 3200;

export const SCRIPT: Step[] = [
  {
    after: 1400,
    by: 'demo',
    action: { type: 'editor', id: 'cursor' },
  },
  {
    after: 1700,
    by: 'demo',
    action: { type: 'transport', transport: 'local' },
  },
  {
    after: 1700,
    by: 'demo',
    action: { type: 'scope', scope: 'everywhere' },
  },
  {
    after: 2200,
    by: 'person',
    press: 'copy',
    action: { type: 'copied' },
    isAnswered: hasCopied,
  },
  { after: CONNECT_MS, action: { type: 'connected' } },
];

/** Under reduced motion the card rests connected, on the config the demonstration ends with. */
export const RESTING: InstallState = {
  editorId: 'cursor',
  transport: 'local',
  scope: 'everywhere',
  connection: 'connected',
};

export const LOOP_AFTER_MS = 3800;

import type { SeriesSlot } from '@/registry/ndeko/lib/agent-run';
import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

/** A fictional server: the address answers nothing. */
export const SERVER = {
  title: 'Harbor docs',
  name: 'harbor',
  url: 'https://mcp.example.dev/mcp',
  localCommand: 'npx',
  localArgs: ['-y', '@harbor-example/mcp'],
  toolCount: 7,
};

export type Transport = 'remote' | 'local';

export type Scope = 'project' | 'everywhere';

export type EditorId =
  'claude-code' | 'cursor' | 'vs-code' | 'windsurf' | 'zed' | 'codex';

export type Editor = {
  id: EditorId;
  name: string;
  /** The mark of the editor when the mark set holds it; its initial on a tile otherwise. */
  brand?: BrandSlug;
  initial: string;
  /** The colour the card takes while it waits for this editor. */
  series: SeriesSlot;
  /** Said under the switches when the editor keeps one list of servers for every project. */
  scopeNote?: string;
};

export const EDITORS: Editor[] = [
  {
    id: 'claude-code',
    name: 'Claude Code',
    brand: 'claudecode',
    initial: 'C',
    series: 1,
  },
  { id: 'cursor', name: 'Cursor', brand: 'cursor', initial: 'C', series: 2 },
  { id: 'vs-code', name: 'VS Code', initial: 'V', series: 3 },
  {
    id: 'windsurf',
    name: 'Windsurf',
    brand: 'windsurf',
    initial: 'W',
    series: 4,
    scopeNote: 'Windsurf keeps one list of servers for every project',
  },
  { id: 'zed', name: 'Zed', brand: 'zed', initial: 'Z', series: 5 },
  {
    id: 'codex',
    name: 'Codex',
    brand: 'codex',
    initial: 'C',
    series: 1,
    scopeNote: 'Codex keeps its servers in one file for every project',
  },
];

export function editorOf(id: EditorId) {
  const editor = EDITORS.find((candidate) => candidate.id === id);
  return editor ?? EDITORS[0];
}

export type SnippetLanguage = 'bash' | 'json' | 'toml' | 'fields';

export type Snippet = {
  /** A terminal, the path of a file, or the settings screen the values go in. */
  label: string;
  language: SnippetLanguage;
  lines: string[];
  /** What Copy puts on the clipboard. */
  copyText: string;
  copyLabel: string;
};

const JSON_INDENT = 2;

function linesOfJson(value: unknown) {
  const text = JSON.stringify(value, null, JSON_INDENT);
  return text.split('\n');
}

function snippetOfLines(
  label: string,
  language: SnippetLanguage,
  lines: string[]
): Snippet {
  return {
    label,
    language,
    lines,
    copyText: lines.join('\n'),
    copyLabel: 'Copy',
  };
}

function localCommandLine() {
  const args = SERVER.localArgs.join(' ');
  return `${SERVER.localCommand} ${args}`;
}

function scopeFlagOf(scope: Scope) {
  if (scope === 'everywhere') {
    return ' --scope user';
  }
  return '';
}

function claudeCodeSnippet(transport: Transport, scope: Scope) {
  const scopeFlag = scopeFlagOf(scope);
  if (transport === 'local') {
    const command = localCommandLine();
    const line = `claude mcp add${scopeFlag} ${SERVER.name} -- ${command}`;
    return snippetOfLines('Terminal', 'bash', [line]);
  }
  const line = `claude mcp add --transport http${scopeFlag} ${SERVER.name} ${SERVER.url}`;
  return snippetOfLines('Terminal', 'bash', [line]);
}

function mcpServersEntryOf(transport: Transport) {
  if (transport === 'local') {
    return { command: SERVER.localCommand, args: SERVER.localArgs };
  }
  return { url: SERVER.url };
}

function cursorPathOf(scope: Scope) {
  if (scope === 'everywhere') {
    return '~/.cursor/mcp.json';
  }
  return '.cursor/mcp.json';
}

function cursorSnippet(transport: Transport, scope: Scope) {
  const entry = mcpServersEntryOf(transport);
  const lines = linesOfJson({ mcpServers: { [SERVER.name]: entry } });
  return snippetOfLines(cursorPathOf(scope), 'json', lines);
}

function vsCodeEntryOf(transport: Transport) {
  if (transport === 'local') {
    return {
      type: 'stdio',
      command: SERVER.localCommand,
      args: SERVER.localArgs,
    };
  }
  return { type: 'http', url: SERVER.url };
}

/** In a workspace VS Code reads a file; for every workspace its command line adds the server to the user profile. */
function vsCodeSnippet(transport: Transport, scope: Scope) {
  const entry = vsCodeEntryOf(transport);
  if (scope === 'everywhere') {
    const config = JSON.stringify({ name: SERVER.name, ...entry });
    const line = `code --add-mcp '${config}'`;
    return snippetOfLines('Terminal', 'bash', [line]);
  }
  const lines = linesOfJson({ servers: { [SERVER.name]: entry } });
  return snippetOfLines('.vscode/mcp.json', 'json', lines);
}

function windsurfSnippet(transport: Transport): Snippet {
  if (transport === 'local') {
    const command = localCommandLine();
    return {
      label: 'Windsurf, MCP settings',
      language: 'fields',
      lines: [`Name     ${SERVER.name}`, `Command  ${command}`],
      copyText: command,
      copyLabel: 'Copy the command',
    };
  }
  return {
    label: 'Windsurf, MCP settings',
    language: 'fields',
    lines: [
      `Name       ${SERVER.name}`,
      'Transport  Streamable HTTP',
      `Address    ${SERVER.url}`,
    ],
    copyText: SERVER.url,
    copyLabel: 'Copy the address',
  };
}

function zedPathOf(scope: Scope) {
  if (scope === 'everywhere') {
    return '~/.config/zed/settings.json';
  }
  return '.zed/settings.json';
}

function zedSnippet(transport: Transport, scope: Scope) {
  const entry = mcpServersEntryOf(transport);
  const lines = linesOfJson({ context_servers: { [SERVER.name]: entry } });
  return snippetOfLines(zedPathOf(scope), 'json', lines);
}

function codexSnippet(transport: Transport) {
  const header = `[mcp_servers.${SERVER.name}]`;
  if (transport === 'local') {
    const args = JSON.stringify(SERVER.localArgs).replaceAll(',', ', ');
    const lines = [
      header,
      `command = "${SERVER.localCommand}"`,
      `args = ${args}`,
    ];
    return snippetOfLines('~/.codex/config.toml', 'toml', lines);
  }
  const lines = [header, `url = "${SERVER.url}"`];
  return snippetOfLines('~/.codex/config.toml', 'toml', lines);
}

/** The config each editor reads, in the form its own documentation gives. */
export function snippetOf(
  editorId: EditorId,
  transport: Transport,
  scope: Scope
): Snippet {
  switch (editorId) {
    case 'claude-code':
      return claudeCodeSnippet(transport, scope);
    case 'cursor':
      return cursorSnippet(transport, scope);
    case 'vs-code':
      return vsCodeSnippet(transport, scope);
    case 'windsurf':
      return windsurfSnippet(transport);
    case 'zed':
      return zedSnippet(transport, scope);
    case 'codex':
      return codexSnippet(transport);
  }
}
